353→func benchFlattenTree(fileCount, fileSizeLines int) func(*testing.B) {
354→	return func(b *testing.B) {
355→		repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{
356→			FileCount:     fileCount,
357→			FileSizeLines: fileSizeLines,
358→		})
359→
360→		// Get HEAD tree
361→		head, err := repo.Repo.Head()
362→		if err != nil {
363→			b.Fatalf("head: %v", err)
364→		}
365→		commit, err := repo.Repo.CommitObject(head.Hash())
366→		if err != nil {
367→			b.Fatalf("commit: %v", err)
368→		}
369→		tree, err := commit.Tree()
370→		if err != nil {
371→			b.Fatalf("tree: %v", err)
372→		}
373→
374→		b.ResetTimer()
375→		for range b.N {
376→			entries := make(map[string]object.TreeEntry, fileCount)
377→			if err := checkpoint.FlattenTree(repo.Repo, tree, "", entries); err != nil {
378→				b.Fatalf("FlattenTree: %v", err)
379→			}
380→		}
381→	}
382→}
