390→func benchBuildTree(entryCount int) func(*testing.B) {
391→	return func(b *testing.B) {
392→		repo := benchutil.NewBenchRepo(b, benchutil.RepoOpts{
393→			FileCount: entryCount,
394→		})
395→
396→		// Flatten the HEAD tree to get realistic entries
397→		head, err := repo.Repo.Head()
398→		if err != nil {
399→			b.Fatalf("head: %v", err)
400→		}
401→		commit, err := repo.Repo.CommitObject(head.Hash())
402→		if err != nil {
403→			b.Fatalf("commit: %v", err)
404→		}
405→		tree, err := commit.Tree()
406→		if err != nil {
407→			b.Fatalf("tree: %v", err)
408→		}
409→		entries := make(map[string]object.TreeEntry, entryCount)
410→		if err := checkpoint.FlattenTree(repo.Repo, tree, "", entries); err != nil {
411→			b.Fatalf("FlattenTree: %v", err)
412→		}
413→
414→		// Open a fresh repo handle for building (to avoid storer cache effects)
415→		freshRepo, err := gogit.PlainOpen(repo.Dir)
416→		if err != nil {
417→			b.Fatalf("open: %v", err)
418→		}
419→
420→		b.ResetTimer()
421→		for range b.N {
422→			_, buildErr := checkpoint.BuildTreeFromEntries(freshRepo, entries)
423→			if buildErr != nil {
424→				b.Fatalf("BuildTreeFromEntries: %v", buildErr)
425→			}
426→		}
427→	}
428→}
