 15→// --- Helpers ---
 16→
 17→// benchInitBareRepo creates a bare git repo for benchmarks.
 18→func benchInitBareRepo(b *testing.B) *gogit.Repository {
 19→	b.Helper()
 20→	repo, err := gogit.PlainInit(b.TempDir(), true)
 21→	if err != nil {
 22→		b.Fatalf("git init: %v", err)
 23→	}
 24→	return repo
 25→}
 26→
 27→// benchCreateBlob stores a blob in the repo.
 28→func benchCreateBlob(b *testing.B, repo *gogit.Repository, content string) plumbing.Hash {
 29→	b.Helper()
 30→	hash, err := checkpoint.CreateBlobFromContent(repo, []byte(content))
 31→	if err != nil {
 32→		b.Fatalf("create blob: %v", err)
 33→	}
 34→	return hash
 35→}
