 37→// buildShardedMetadataTree builds a realistic metadata branch tree with N checkpoints
 38→// distributed across shards. Each checkpoint has 5 files (metadata.json, full.jsonl,
 39→// prompt.txt, context.md, content_hash.txt) matching the real storage format.
 40→//
 41→// Returns the root tree hash.
 42→func buildShardedMetadataTree(b *testing.B, repo *gogit.Repository, checkpointCount int) plumbing.Hash {
 43→	b.Helper()
 44→
 45→	entries := make(map[string]object.TreeEntry, checkpointCount*5)
 46→	for i := range checkpointCount {
 47→		// Generate a fake checkpoint ID (12 hex chars) spread across shards
 48→		cpID := fmt.Sprintf("%02x%010d", i%256, i)
 49→		shard := cpID[:2]
 50→		suffix := cpID[2:]
 51→		base := shard + "/" + suffix + "/"
 52→
 53→		for _, file := range []struct {
 54→			name    string
 55→			content string
 56→		}{
 57→			{"metadata.json", fmt.Sprintf(`{"checkpoint_id":"%s","session_count":1}`, cpID)},
 58→			{"0/metadata.json", fmt.Sprintf(`{"checkpoint_id":"%s","session_id":"s-%d"}`, cpID, i)},
 59→			{"0/full.jsonl", fmt.Sprintf(`{"type":"assistant","content":"checkpoint %d data padding %0200d"}`, i, i)},
 60→			{"0/prompt.txt", fmt.Sprintf("Implement feature %d", i)},
 61→			{"0/content_hash.txt", fmt.Sprintf("sha256:%064x", i)},
 62→		} {
 63→			blob, err := checkpoint.CreateBlobFromContent(repo, []byte(file.content))
 64→			if err != nil {
 65→				b.Fatalf("create blob: %v", err)
 66→			}
 67→			path := base + file.name
 68→			entries[path] = object.TreeEntry{
 69→				Name: file.name,
 70→				Mode: filemode.Regular,
 71→				Hash: blob,
 72→			}
 73→		}
 74→	}
 75→
 76→	hash, err := checkpoint.BuildTreeFromEntries(repo, entries)
 77→	if err != nil {
 78→		b.Fatalf("build tree: %v", err)
 79→	}
 80→	return hash
 81→}
 82→
 83→// buildFlatFileTree builds a tree with N files in a directory structure
 84→// resembling a real working tree (files under src/, pkg/, etc.).
 85→func buildFlatFileTree(b *testing.B, repo *gogit.Repository, fileCount int) plumbing.Hash {
 86→	b.Helper()
 87→
 88→	entries := make(map[string]object.TreeEntry, fileCount)
 89→	dirs := []string{"src", "pkg", "internal", "cmd", "api"}
 90→	for i := range fileCount {
 91→		dir := dirs[i%len(dirs)]
 92→		name := fmt.Sprintf("%s/file_%04d.go", dir, i)
 93→		blob := benchCreateBlob(b, repo, fmt.Sprintf("package main\n// file %d\nfunc f%d() {}\n", i, i))
 94→		entries[name] = object.TreeEntry{
 95→			Name: fmt.Sprintf("file_%04d.go", i),
 96→			Mode: filemode.Regular,
 97→			Hash: blob,
 98→		}
 99→	}
100→
101→	hash, err := checkpoint.BuildTreeFromEntries(repo, entries)
102→	if err != nil {
103→		b.Fatalf("build tree: %v", err)
104→	}
105→	return hash
106→}
