108→// --- UpdateSubtree benchmarks (metadata branch path) ---
109→// The key dimension is number of prior checkpoints, since UpdateSubtree is O(depth)
110→// while FlattenTree+BuildTreeFromEntries is O(total checkpoints).
111→
112→func BenchmarkUpdateSubtree(b *testing.B) {
113→	for _, count := range []int{1, 10, 50, 200, 500} {
114→		b.Run(fmt.Sprintf("Checkpoints_%d/TreeSurgery", count), benchUpdateSubtreeTreeSurgery(count))
115→		b.Run(fmt.Sprintf("Checkpoints_%d/FlattenRebuild", count), benchUpdateSubtreeFlattenRebuild(count))
116→	}
117→}
