119→// benchUpdateSubtreeTreeSurgery benchmarks adding a checkpoint to a metadata tree
120→// using UpdateSubtree (O(depth) tree surgery).
121→func benchUpdateSubtreeTreeSurgery(priorCheckpoints int) func(*testing.B) {
122→	return func(b *testing.B) {
123→		repo := benchInitBareRepo(b)
