package benchutil

import (
	"context"
	"fmt"
	"os"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"
	"github.com/entireio/cli/cmd/entire/cli/checkpoint/id"
	"github.com/entireio/cli/cmd/entire/cli/paths"

	gogit "github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// --- WriteTemporary benchmarks ---
// WriteTemporary is the hot path that fires on every agent turn (SaveStep).
// It builds a git tree from changed files and commits to the shadow branch.

func BenchmarkWriteTemporary(b *testing.B) {
	b.Run("FirstCheckpoint_SmallRepo", benchWriteTemporaryFirstCheckpoint(10, 100))
	b.Run("FirstCheckpoint_LargeRepo", benchWriteTemporaryFirstCheckpoint(50, 500))
	b.Run("Incremental_FewFiles", benchWriteTemporaryIncremental(3, 0, 0))
	b.Run("Incremental_ManyFiles", benchWriteTemporaryIncremental(30, 10, 5))
	b.Run("Incremental_LargeFiles", benchWriteTemporaryIncrementalLargeFiles(2, 10000))
	b.Run("Dedup_NoChanges", benchWriteTemporaryDedup())
	b.Run("ManyPriorCheckpoints", benchWriteTemporaryWithHistory(50))
}

// benchWriteTemporaryFirstCheckpoint benchmarks the first checkpoint of a session.
// The first checkpoint captures all changed files via `git status`, which is heavier
// than incremental checkpoints.
func benchWriteTemporaryFirstCheckpoint(fileCount, fileSizeLines int) func(*testing.B) {
	return func(b *testing.B) {
		repo := NewBenchRepo(b, RepoOpts{
			FileCount:     fileCount,
			FileSizeLines: fileSizeLines,
		})
		sessionID := repo.CreateSessionState(b, SessionOpts{})

		// Modify a few files to create a dirty working directory
		for i := range 3 {
			name := fmt.Sprintf("src/file_%03d.go", i)
			repo.WriteFile(b, name, GenerateGoFile(9000+i, fileSizeLines))
		}

		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
		metadataDirAbs := filepath.Join(repo.Dir, metadataDir)
		if err := os.MkdirAll(metadataDirAbs, 0o750); err != nil {
			b.Fatalf("mkdir metadata: %v", err)
		}

		// WriteTemporary uses paths.WorktreeRoot() which requires cwd to be in the repo.
		b.Chdir(repo.Dir)

		ctx := context.Background()
		b.ResetTimer()
		for i := range b.N {
			// Re-create the shadow branch state for each iteration so we always
			// measure the first-checkpoint path (which runs collectChangedFiles).
			// We use a unique session ID per iteration to get a fresh shadow branch.
			sid := fmt.Sprintf("bench-first-%d", i)
			_, writeErr := repo.Store.WriteTemporary(ctx, checkpoint.WriteTemporaryOptions{
				SessionID:         sid,
				BaseCommit:        repo.HeadHash,
				WorktreeID:        repo.WorktreeID,
				ModifiedFiles:     []string{"src/file_000.go", "src/file_001.go", "src/file_002.go"},
				MetadataDir:       metadataDir,
				MetadataDirAbs:    metadataDirAbs,
				CommitMessage:     "benchmark checkpoint",
				AuthorName:        "Bench",
				AuthorEmail:       "bench@test.com",
				IsFirstCheckpoint: true,
			})
			if writeErr != nil {
				b.Fatalf("WriteTemporary: %v", writeErr)
			}
		}
	}
}

// benchWriteTemporaryIncremental benchmarks subsequent checkpoints (not the first).
// These skip collectChangedFiles and only process the provided file lists.
func benchWriteTemporaryIncremental(modified, newFiles, deleted int) func(*testing.B) {
	return func(b *testing.B) {
		repo := NewBenchRepo(b, RepoOpts{
			FileCount:     max(modified+newFiles, 10),
			FileSizeLines: 100,
		})
		sessionID := repo.CreateSessionState(b, SessionOpts{})

		// Seed one checkpoint so subsequent ones are not IsFirstCheckpoint
		repo.SeedShadowBranch(b, sessionID, 1, 3)

		// Prepare file lists
		modifiedFiles := make([]string, 0, modified)
		for i := range modified {
			name := fmt.Sprintf("src/file_%03d.go", i)
			repo.WriteFile(b, name, GenerateGoFile(8000+i, 100))
			modifiedFiles = append(modifiedFiles, name)
		}
		newFileList := make([]string, 0, newFiles)
		for i := range newFiles {
			name := fmt.Sprintf("src/new_%03d.go", i)
			repo.WriteFile(b, name, GenerateGoFile(7000+i, 100))
			newFileList = append(newFileList, name)
		}
		deletedFiles := make([]string, 0, deleted)
		for i := range deleted {
			deletedFiles = append(deletedFiles, fmt.Sprintf("src/file_%03d.go", modified+newFiles+i))
		}

		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
		metadataDirAbs := filepath.Join(repo.Dir, metadataDir)
		if err := os.MkdirAll(metadataDirAbs, 0o750); err != nil {
			b.Fatalf("mkdir metadata: %v", err)
		}

		b.Chdir(repo.Dir)

		ctx := context.Background()
		b.ResetTimer()
		for range b.N {
			_, writeErr := repo.Store.WriteTemporary(ctx, checkpoint.WriteTemporaryOptions{
				SessionID:         sessionID,
				BaseCommit:        repo.HeadHash,
				WorktreeID:        repo.WorktreeID,
				ModifiedFiles:     modifiedFiles,
				NewFiles:          newFileList,
				DeletedFiles:      deletedFiles,
				MetadataDir:       metadataDir,
				MetadataDirAbs:    metadataDirAbs,
				CommitMessage:     "benchmark checkpoint",
				AuthorName:        "Bench",
				AuthorEmail:       "bench@test.com",
				IsFirstCheckpoint: false,
			})
			if writeErr != nil {
				b.Fatalf("WriteTemporary: %v", writeErr)
			}
		}
	}
}

// benchWriteTemporaryIncrementalLargeFiles benchmarks checkpoints with large files.
func benchWriteTemporaryIncrementalLargeFiles(fileCount, linesPerFile int) func(*testing.B) {
	return func(b *testing.B) {
		repo := NewBenchRepo(b, RepoOpts{
			FileCount:     fileCount,
			FileSizeLines: linesPerFile,
		})
		sessionID := repo.CreateSessionState(b, SessionOpts{})
		repo.SeedShadowBranch(b, sessionID, 1, fileCount)

		modifiedFiles := make([]string, 0, fileCount)
		for i := range fileCount {
			name := fmt.Sprintf("src/file_%03d.go", i)
			repo.WriteFile(b, name, GenerateGoFile(6000+i, linesPerFile))
			modifiedFiles = append(modifiedFiles, name)
		}

		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
		metadataDirAbs := filepath.Join(repo.Dir, metadataDir)
		if err := os.MkdirAll(metadataDirAbs, 0o750); err != nil {
			b.Fatalf("mkdir metadata: %v", err)
		}

		b.Chdir(repo.Dir)

		ctx := context.Background()
		b.ResetTimer()
		for range b.N {
			_, writeErr := repo.Store.WriteTemporary(ctx, checkpoint.WriteTemporaryOptions{
				SessionID:         sessionID,
				BaseCommit:        repo.HeadHash,
				WorktreeID:        repo.WorktreeID,
				ModifiedFiles:     modifiedFiles,
				MetadataDir:       metadataDir,
				MetadataDirAbs:    metadataDirAbs,
				CommitMessage:     "benchmark checkpoint",
				AuthorName:        "Bench",
				AuthorEmail:       "bench@test.com",
				IsFirstCheckpoint: false,
			})
			if writeErr != nil {
				b.Fatalf("WriteTemporary: %v", writeErr)
			}
		}
	}
}

// benchWriteTemporaryDedup benchmarks the dedup fast-path where the tree hash
// matches the previous checkpoint, so the write is skipped.
func benchWriteTemporaryDedup() func(*testing.B) {
	return func(b *testing.B) {
		repo := NewBenchRepo(b, RepoOpts{FileCount: 10})
		sessionID := repo.CreateSessionState(b, SessionOpts{})
		repo.SeedShadowBranch(b, sessionID, 1, 3)

		// Don't modify any files — tree will match the previous checkpoint
		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
		metadataDirAbs := filepath.Join(repo.Dir, metadataDir)

		b.Chdir(repo.Dir)

		ctx := context.Background()
		b.ResetTimer()
		for range b.N {
			result, writeErr := repo.Store.WriteTemporary(ctx, checkpoint.WriteTemporaryOptions{
				SessionID:         sessionID,
				BaseCommit:        repo.HeadHash,
				WorktreeID:        repo.WorktreeID,
				ModifiedFiles:     []string{"src/file_000.go", "src/file_001.go", "src/file_002.go"},
				MetadataDir:       metadataDir,
				MetadataDirAbs:    metadataDirAbs,
				CommitMessage:     "benchmark checkpoint",
				AuthorName:        "Bench",
				AuthorEmail:       "bench@test.com",
				IsFirstCheckpoint: false,
			})
			if writeErr != nil {
				b.Fatalf("WriteTemporary: %v", writeErr)
			}
			if !result.Skipped {
				b.Fatal("expected dedup skip")
			}
		}
	}
}

// benchWriteTemporaryWithHistory benchmarks WriteTemporary when the shadow branch
// already has many prior checkpoint commits.
func benchWriteTemporaryWithHistory(priorCheckpoints int) func(*testing.B) {
	return func(b *testing.B) {
		repo := NewBenchRepo(b, RepoOpts{FileCount: 10})
		sessionID := repo.CreateSessionState(b, SessionOpts{})
		repo.SeedShadowBranch(b, sessionID, priorCheckpoints, 3)

		// Modify files for the new checkpoint
		for i := range 3 {
			name := fmt.Sprintf("src/file_%03d.go", i)
			repo.WriteFile(b, name, GenerateGoFile(5000+i, 100))
		}

		metadataDir := paths.SessionMetadataDirFromSessionID(sessionID)
		metadataDirAbs := filepath.Join(repo.Dir, metadataDir)
		if err := os.MkdirAll(metadataDirAbs, 0o750); err != nil {
			b.Fatalf("mkdir metadata: %v", err)
		}

		b.Chdir(repo.Dir)

		ctx := context.Background()
		b.ResetTimer()
		for range b.N {
			_, writeErr := repo.Store.WriteTemporary(ctx, checkpoint.WriteTemporaryOptions{
				SessionID:         sessionID,
				BaseCommit:        repo.HeadHash,
				WorktreeID:        repo.WorktreeID,
				ModifiedFiles:     []string{"src/file_000.go", "src/file_001.go", "src/file_002.go"},
				MetadataDir:       metadataDir,
				MetadataDirAbs:    metadataDirAbs,
				CommitMessage:     "benchmark checkpoint",
				AuthorName:        "Bench",
				AuthorEmail:       "bench@test.com",
				IsFirstCheckpoint: false,
			})
			if writeErr != nil {
				b.Fatalf("WriteTemporary: %v", writeErr)
			}
		}
	}
}

// --- WriteCommitted benchmarks ---
// WriteCommitted fires during PostCommit condensation when the user does `git commit`.
// It writes session metadata to the entire/checkpoints/v1 branch.

func BenchmarkWriteCommitted(b *testing.B) {
	b.Run("SmallTranscript", benchWriteCommitted(20, 500, 3, 0))
	b.Run("MediumTranscript", benchWriteCommitted(200, 500, 15, 0))
	b.Run("LargeTranscript", benchWriteCommitted(2000, 500, 50, 0))
	b.Run("HugeTranscript", benchWriteCommitted(10000, 1000, 100, 0))
	b.Run("EmptyMetadataBranch", benchWriteCommitted(200, 500, 15, 0))
	b.Run("FewPriorCheckpoints", benchWriteCommitted(200, 500, 15, 10))
	b.Run("ManyPriorCheckpoints", benchWriteCommitted(200, 500, 15, 200))
}

// benchWriteCommitted benchmarks writing to the entire/checkpoints/v1 branch.
func benchWriteCommitted(messageCount, avgMsgBytes, filesTouched, priorCheckpoints int) func(*testing.B) {
	return func(b *testing.B) {
		repo := NewBenchRepo(b, RepoOpts{
			FileCount: max(filesTouched, 10),
		})

		// Seed prior checkpoints if requested
		if priorCheckpoints > 0 {
			repo.SeedMetadataBranch(b, priorCheckpoints)
		}

		// Pre-generate transcript data (not part of the benchmark)
		files := make([]string, 0, filesTouched)
		for i := range filesTouched {
			files = append(files, fmt.Sprintf("src/file_%03d.go", i))
		}
		transcript := GenerateTranscript(TranscriptOpts{
			MessageCount:    messageCount,
			AvgMessageBytes: avgMsgBytes,
			IncludeToolUse:  true,
			FilesTouched:    files,
		})
		prompts := []string{"Implement the feature", "Fix the bug in handler"}

		b.ResetTimer()
		b.ReportMetric(float64(len(transcript)), "transcript_bytes")

		ctx := context.Background()
		for i := range b.N {
			cpID, err := id.Generate()
			if err != nil {
				b.Fatalf("generate ID: %v", err)
			}
			err = repo.Store.WriteCommitted(ctx, checkpoint.WriteCommittedOptions{
				CheckpointID:     cpID,
				SessionID:        fmt.Sprintf("bench-session-%d", i),
				Strategy:         "manual-commit",
				Transcript:       transcript,
				Prompts:          prompts,
				FilesTouched:     files,
				CheckpointsCount: 5,
				AuthorName:       "Bench",
				AuthorEmail:      "bench@test.com",
			})
			if err != nil {
				b.Fatalf("WriteCommitted: %v", err)
			}
		}
	}
}

// --- FlattenTree + BuildTreeFromEntries benchmarks ---
// These isolate the git plumbing cost that's shared by both hot paths.

func BenchmarkFlattenTree(b *testing.B) {
	b.Run("10files", benchFlattenTree(10, 100))
	b.Run("50files", benchFlattenTree(50, 100))
	b.Run("200files", benchFlattenTree(200, 50))
}

func benchFlattenTree(fileCount, fileSizeLines int) func(*testing.B) {
	return func(b *testing.B) {
		repo := NewBenchRepo(b, RepoOpts{
			FileCount:     fileCount,
			FileSizeLines: fileSizeLines,
		})

		// Get HEAD tree
		head, err := repo.Repo.Head()
		if err != nil {
			b.Fatalf("head: %v", err)
		}
		commit, err := repo.Repo.CommitObject(head.Hash())
		if err != nil {
			b.Fatalf("commit: %v", err)
		}
		tree, err := commit.Tree()
		if err != nil {
			b.Fatalf("tree: %v", err)
		}

		b.ResetTimer()
		for range b.N {
			entries := make(map[string]object.TreeEntry, fileCount)
			if err := checkpoint.FlattenTree(repo.Repo, tree, "", entries); err != nil {
				b.Fatalf("FlattenTree: %v", err)
			}
		}
	}
}

func BenchmarkBuildTreeFromEntries(b *testing.B) {
	b.Run("10entries", benchBuildTree(10))
	b.Run("50entries", benchBuildTree(50))
	b.Run("200entries", benchBuildTree(200))
}

func benchBuildTree(entryCount int) func(*testing.B) {
	return func(b *testing.B) {
		repo := NewBenchRepo(b, RepoOpts{
			FileCount: entryCount,
		})

		// Flatten the HEAD tree to get realistic entries
		head, err := repo.Repo.Head()
		if err != nil {
			b.Fatalf("head: %v", err)
		}
		commit, err := repo.Repo.CommitObject(head.Hash())
		if err != nil {
			b.Fatalf("commit: %v", err)
		}
		tree, err := commit.Tree()
		if err != nil {
			b.Fatalf("tree: %v", err)
		}
		entries := make(map[string]object.TreeEntry, entryCount)
		if err := checkpoint.FlattenTree(repo.Repo, tree, "", entries); err != nil {
			b.Fatalf("FlattenTree: %v", err)
		}

		// Open a fresh repo handle for building (to avoid storer cache effects)
		freshRepo, err := gogit.PlainOpen(repo.Dir)
		if err != nil {
			b.Fatalf("open: %v", err)
		}

		b.ResetTimer()
		for range b.N {
			_, buildErr := checkpoint.BuildTreeFromEntries(freshRepo, entries)
			if buildErr != nil {
				b.Fatalf("BuildTreeFromEntries: %v", buildErr)
			}
		}
	}
}

package benchutil

import (
	"fmt"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/checkpoint"

	gogit "github.com/go-git/go-git/v5"
	"github.com/go-git/go-git/v5/plumbing"
	"github.com/go-git/go-git/v5/plumbing/filemode"
	"github.com/go-git/go-git/v5/plumbing/object"
)

// --- Helpers ---

// benchInitBareRepo creates a bare git repo for benchmarks.
func benchInitBareRepo(b *testing.B) *gogit.Repository {
	b.Helper()
	repo, err := gogit.PlainInit(b.TempDir(), true)
	if err != nil {
		b.Fatalf("git init: %v", err)
	}
	return repo
}

// benchCreateBlob stores a blob in the repo.
func benchCreateBlob(b *testing.B, repo *gogit.Repository, content string) plumbing.Hash {
	b.Helper()
	hash, err := checkpoint.CreateBlobFromContent(repo, []byte(content))
	if err != nil {
		b.Fatalf("create blob: %v", err)
	}
	return hash
}

// buildShardedMetadataTree builds a realistic metadata branch tree with N checkpoints
// distributed across shards. Each checkpoint has 5 files (metadata.json, full.jsonl,
// prompt.txt, context.md, content_hash.txt) matching the real storage format.
//
// Returns the root tree hash.
func buildShardedMetadataTree(b *testing.B, repo *gogit.Repository, checkpointCount int) plumbing.Hash {
	b.Helper()

	entries := make(map[string]object.TreeEntry, checkpointCount*5)
	for i := range checkpointCount {
		// Generate a fake checkpoint ID (12 hex chars) spread across shards
		cpID := fmt.Sprintf("%02x%010d", i%256, i)
		shard := cpID[:2]
		suffix := cpID[2:]
		base := shard + "/" + suffix + "/"

		for _, file := range []struct {
			name    string
			content string
		}{
			{"metadata.json", fmt.Sprintf(`{"checkpoint_id":"%s","session_count":1}`, cpID)},
			{"0/metadata.json", fmt.Sprintf(`{"checkpoint_id":"%s","session_id":"s-%d"}`, cpID, i)},
			{"0/full.jsonl", fmt.Sprintf(`{"type":"assistant","content":"checkpoint %d data padding %0200d"}`, i, i)},
			{"0/prompt.txt", fmt.Sprintf("Implement feature %d", i)},
			{"0/content_hash.txt", fmt.Sprintf("sha256:%064x", i)},
		} {
			blob, err := checkpoint.CreateBlobFromContent(repo, []byte(file.content))
			if err != nil {
				b.Fatalf("create blob: %v", err)
			}
			path := base + file.name
			entries[path] = object.TreeEntry{
				Name: file.name,
				Mode: filemode.Regular,
				Hash: blob,
			}
		}
	}

	hash, err := checkpoint.BuildTreeFromEntries(repo, entries)
	if err != nil {
		b.Fatalf("build tree: %v", err)
	}
	return hash
}

// buildFlatFileTree builds a tree with N files in a directory structure
// resembling a real working tree (files under src/, pkg/, etc.).
func buildFlatFileTree(b *testing.B, repo *gogit.Repository, fileCount int) plumbing.Hash {
	b.Helper()

	entries := make(map[string]object.TreeEntry, fileCount)
	dirs := []string{"src", "pkg", "internal", "cmd", "api"}
	for i := range fileCount {
		dir := dirs[i%len(dirs)]
		name := fmt.Sprintf("%s/file_%04d.go", dir, i)
		blob := benchCreateBlob(b, repo, fmt.Sprintf("package main\n// file %d\nfunc f%d() {}\n", i, i))
		entries[name] = object.TreeEntry{
			Name: fmt.Sprintf("file_%04d.go", i),
			Mode: filemode.Regular,
			Hash: blob,
		}
	}

	hash, err := checkpoint.BuildTreeFromEntries(repo, entries)
	if err != nil {
		b.Fatalf("build tree: %v", err)
	}
	return hash
}

// --- UpdateSubtree benchmarks (metadata branch path) ---
// The key dimension is number of prior checkpoints, since UpdateSubtree is O(depth)
// while FlattenTree+BuildTreeFromEntries is O(total checkpoints).

func BenchmarkUpdateSubtree(b *testing.B) {
	for _, count := range []int{1, 10, 50, 200, 500} {
		b.Run(fmt.Sprintf("Checkpoints_%d/TreeSurgery", count), benchUpdateSubtreeTreeSurgery(count))
		b.Run(fmt.Sprintf("Checkpoints_%d/FlattenRebuild", count), benchUpdateSubtreeFlattenRebuild(count))
	}
}

// benchUpdateSubtreeTreeSurgery benchmarks adding a checkpoint to a metadata tree
// using UpdateSubtree (O(depth) tree surgery).
func benchUpdateSubtreeTreeSurgery(priorCheckpoints int) func(*testing.B) {
	return func(b *testing.B) {
		repo := benchInitBareRepo(b)
		rootTree := buildShardedMetadataTree(b, repo, priorCheckpoints)

		// Prepare the new checkpoint data (5 files)
		newBlobs := make([]plumbing.Hash, 5)
		for i := range newBlobs {
			newBlobs[i] = benchCreateBlob(b, repo, fmt.Sprintf("new checkpoint file %d content", i))
		}

		// Build the checkpoint subtree once
		cpEntries := make(map[string]object.TreeEntry, 5)
		for i, name := range []string{"metadata.json", "0/metadata.json", "0/full.jsonl", "0/prompt.txt", "0/content_hash.txt"} {
			cpEntries[name] = object.TreeEntry{
				Name: name,
				Mode: filemode.Regular,
				Hash: newBlobs[i],
			}
		}
		cpTreeHash, err := checkpoint.BuildTreeFromEntries(repo, cpEntries)
		if err != nil {
			b.Fatalf("build checkpoint tree: %v", err)
		}

		shardPrefix := "ff" // Use a shard that likely doesn't exist yet
		shardSuffix := "newckpt1234"

		b.ResetTimer()
		for range b.N {
			_, err := checkpoint.UpdateSubtree(repo, rootTree, []string{shardPrefix}, []object.TreeEntry{
				{Name: shardSuffix, Mode: filemode.Dir, Hash: cpTreeHash},
			}, checkpoint.UpdateSubtreeOptions{MergeMode: checkpoint.MergeKeepExisting})
			if err != nil {
				b.Fatalf("UpdateSubtree: %v", err)
			}
		}
	}
}

// benchUpdateSubtreeFlattenRebuild benchmarks the old approach: flatten entire tree,
// add new entries, rebuild from scratch. O(total checkpoints).
func benchUpdateSubtreeFlattenRebuild(priorCheckpoints int) func(*testing.B) {
	return func(b *testing.B) {
		repo := benchInitBareRepo(b)
		rootTree := buildShardedMetadataTree(b, repo, priorCheckpoints)

		// Prepare the new checkpoint entries
		newBlobs := make([]plumbing.Hash, 5)
		for i := range newBlobs {
			newBlobs[i] = benchCreateBlob(b, repo, fmt.Sprintf("new checkpoint file %d content", i))
		}
		newFiles := []struct {
			path string
			hash plumbing.Hash
		}{
			{"ff/newckpt1234/metadata.json", newBlobs[0]},
			{"ff/newckpt1234/0/metadata.json", newBlobs[1]},
			{"ff/newckpt1234/0/full.jsonl", newBlobs[2]},
			{"ff/newckpt1234/0/prompt.txt", newBlobs[3]},
			{"ff/newckpt1234/0/content_hash.txt", newBlobs[4]},
		}

		b.ResetTimer()
		for range b.N {
			// Flatten entire tree
			tree, err := repo.TreeObject(rootTree)
			if err != nil {
				b.Fatalf("read tree: %v", err)
			}
			entries := make(map[string]object.TreeEntry)
			if err := checkpoint.FlattenTree(repo, tree, "", entries); err != nil {
				b.Fatalf("FlattenTree: %v", err)
			}

			// Add new entries
			for _, f := range newFiles {
				entries[f.path] = object.TreeEntry{
					Name: f.path,
					Mode: filemode.Regular,
					Hash: f.hash,
				}
			}

			// Rebuild entire tree
			_, err = checkpoint.BuildTreeFromEntries(repo, entries)
			if err != nil {
				b.Fatalf("BuildTreeFromEntries: %v", err)
			}
		}
	}
}

// --- ApplyTreeChanges benchmarks (working tree / shadow branch path) ---
// Two dimensions: base tree size (total files) and number of changes.

func BenchmarkApplyTreeChanges(b *testing.B) {
	// Dimension 1: Varying base tree size with fixed number of changes
	for _, fileCount := range []int{10, 100, 500} {
		b.Run(fmt.Sprintf("Files_%d_Changes_3/TreeSurgery", fileCount), benchApplyTreeChangesTreeSurgery(fileCount, 3))
		b.Run(fmt.Sprintf("Files_%d_Changes_3/FlattenRebuild", fileCount), benchApplyTreeChangesFlattenRebuild(fileCount, 3))
	}

	// Dimension 2: Varying number of changes with fixed base tree size
	for _, changeCount := range []int{1, 5, 20, 50} {
		b.Run(fmt.Sprintf("Files_200_Changes_%d/TreeSurgery", changeCount), benchApplyTreeChangesTreeSurgery(200, changeCount))
		b.Run(fmt.Sprintf("Files_200_Changes_%d/FlattenRebuild", changeCount), benchApplyTreeChangesFlattenRebuild(200, changeCount))
	}
}

// benchApplyTreeChangesTreeSurgery benchmarks modifying files in a tree
// using ApplyTreeChanges (only touches affected subtrees).
func benchApplyTreeChangesTreeSurgery(fileCount, changeCount int) func(*testing.B) {
	return func(b *testing.B) {
		repo := benchInitBareRepo(b)
		rootTree := buildFlatFileTree(b, repo, fileCount)

		// Prepare changes: modify files spread across directories
		changes := make([]checkpoint.TreeChange, 0, changeCount)
		dirs := []string{"src", "pkg", "internal", "cmd", "api"}
		for i := range changeCount {
			dir := dirs[i%len(dirs)]
			fileIdx := i % fileCount
			path := fmt.Sprintf("%s/file_%04d.go", dir, fileIdx)
			newBlob := benchCreateBlob(b, repo, fmt.Sprintf("modified content %d\n", i))
			changes = append(changes, checkpoint.TreeChange{
				Path: path,
				Entry: &object.TreeEntry{
					Name: fmt.Sprintf("file_%04d.go", fileIdx),
					Mode: filemode.Regular,
					Hash: newBlob,
				},
			})
		}

		b.ResetTimer()
		for range b.N {
			_, err := checkpoint.ApplyTreeChanges(repo, rootTree, changes)
			if err != nil {
				b.Fatalf("ApplyTreeChanges: %v", err)
			}
		}
	}
}

// benchApplyTreeChangesFlattenRebuild benchmarks the old approach for working tree
// modifications: flatten, modify, rebuild.
func benchApplyTreeChangesFlattenRebuild(fileCount, changeCount int) func(*testing.B) {
	return func(b *testing.B) {
		repo := benchInitBareRepo(b)
		rootTree := buildFlatFileTree(b, repo, fileCount)

		// Prepare changes
		type change struct {
			path string
			hash plumbing.Hash
		}
		changes := make([]change, 0, changeCount)
		dirs := []string{"src", "pkg", "internal", "cmd", "api"}
		for i := range changeCount {
			dir := dirs[i%len(dirs)]
			fileIdx := i % fileCount
			path := fmt.Sprintf("%s/file_%04d.go", dir, fileIdx)
			newBlob := benchCreateBlob(b, repo, fmt.Sprintf("modified content %d\n", i))
			changes = append(changes, change{path: path, hash: newBlob})
		}

		b.ResetTimer()
		for range b.N {
			// Flatten entire tree
			tree, err := repo.TreeObject(rootTree)
			if err != nil {
				b.Fatalf("read tree: %v", err)
			}
			entries := make(map[string]object.TreeEntry)
			if err := checkpoint.FlattenTree(repo, tree, "", entries); err != nil {
				b.Fatalf("FlattenTree: %v", err)
			}

			// Apply changes
			for _, c := range changes {
				entries[c.path] = object.TreeEntry{
					Name: c.path,
					Mode: filemode.Regular,
					Hash: c.hash,
				}
			}

			// Rebuild
			_, err = checkpoint.BuildTreeFromEntries(repo, entries)
			if err != nil {
				b.Fatalf("BuildTreeFromEntries: %v", err)
			}
		}
	}
}
